export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, ta = u / g, apexH = u * u / (2 * g);
  const t = sdk.clamp(time, 0, T);
  const h = Math.max(0, u * t - g * t * t / 2);
  const v = u - g * t;
  const a = -g, F = m * g;
  let st = 'Rising';
  if (t <= 0) st = 'Ready to toss';
  else if (t >= T - 1e-6) st = 'Back at launch height';
  else if (Math.abs(t - ta) < 0.005) st = 'At the top';
  else if (t > ta) st = 'Falling';
  const by = 370 - h * 109;
  const bx = 120;
  const f1 = (x) => sdk.format(x, 2);
  const tt = Math.max(t, 0.001);
  const trace = sdk.sample((x) => u - g * x, 0, tt, 10).map(p => ({ x: p[0], y: p[1] }));
  const cont = sdk.sample((x) => u - g * x, tt, Math.max(T, tt + 0.001), 10).map(p => ({ x: p[0], y: p[1] }));
  const t0 = Math.max(0, t - 0.15), t1 = Math.min(1.8, t + 0.15);
  const seg = [{ x: t0, y: u - g * t0 }, { x: t1, y: u - g * t1 }];
  const objs = [];
  objs.push(...sdk.panel({ id: 'lane.motion', x: 10, y: 36, w: 300, h: 370, title: 'The motion', state: st }));
  objs.push(...sdk.panel({ id: 'lane.graph', x: 325, y: 36, w: 305, h: 370, title: 'Velocity over time', state: 'v = u - g t' }));
  objs.push(sdk.axis('axis.height', { x: 62, y: 370, length: 240, orientation: 'y', min: 0, max: 2.2, ticks: [0, 0.5, 1, 1.5, 2], label: 'Height', unit: 'm' }));
  objs.push(sdk.circle('ball.toss', bx, by, 28));
  objs.push(...sdk.vector('vec.a', { x: 88, y: by }, { value: a, direction: 'up' }, { scale: 5, label: 'a', role: 'warning' }));
  objs.push(...sdk.vector('vec.v', { x: 152, y: by }, { value: v, direction: 'up' }, { scale: 10, label: 'v', role: 'input' }));
  objs.push(...sdk.callout(195, sdk.clamp(by - 30, 70, 310), ['v = ' + f1(v) + ' m/s', 'a = ' + f1(a) + ' m/s²', 'F = ' + f1(F) + ' N'], { id: 'callout.toss' }));
  objs.push(sdk.plot('plot.vt', { x: 335, y: 66, w: 285, h: 280, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' } }, series: [{ label: 'v so far', kind: 'line', points: trace }, { label: 'later', kind: 'line', points: cont }, { label: 'slope', kind: 'line', points: seg }] }));
  objs.push(sdk.text('plot.vt.note', 480, 392, 'slope a = -g = ' + f1(a) + ' m/s²', { align: 'middle' }));
  return {
    frame: { width: 640, height: 420, objects: objs, readouts: [{ id: 'velocity', value: v }, { id: 'acceleration', value: a }, { id: 'force', value: F }, { id: 'motionState', value: st }] },
    quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: ta, apexHeight: apexH, height: h, velocity: v, acceleration: a, force: F }
  };
}
